@sealed
class CatalogueHandleImpl extends RustOpaque implements CatalogueHandle {
  // Not to be used by end users
  CatalogueHandleImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  CatalogueHandleImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_CatalogueHandle,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_CatalogueHandle,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_CatalogueHandlePtr,
  );

  /// Parse and append a chunk of the catalogue, in the order given.
  ///
  /// Returns the specs in this chunk that did not parse; the rest are
  /// appended. A spec that fails is skipped rather than failing the whole
  /// catalogue, which is what the Dart loader did before and why one bad
  /// vendored spec cannot take matching out.
  ///
  /// `keys` and `yamls` are parallel lists. A length mismatch is a caller
  /// bug, so it is an error rather than a silent truncation.
  Future<List<SpecLoadFailureDto>> addSpecs({
    required List<String> keys,
    required List<String> yamls,
  }) => RustLib.instance.api.crateApiSpecHandleCatalogueHandleAddSpecs(
    that: this,
    keys: keys,
    yamls: yamls,
  );

  /// The full DTO of the spec at `index`.
  Future<DeviceSpecDto> dtoAt({required int index}) => RustLib.instance.api
      .crateApiSpecHandleCatalogueHandleDtoAt(that: this, index: index);

  /// Every entry's light projection, in catalogue order.
  Future<List<CatalogueEntryDto>> entries() =>
      RustLib.instance.api.crateApiSpecHandleCatalogueHandleEntries(that: this);

  /// Match every spec in the catalogue against a device we are already
  /// connected to, by advertised name and discovered GATT services.
  ///
  /// Two strings in, matched indices out. The by-value twin
  /// (`match_device_to_spec`) shares the axes rule through
  /// [`match_connected_device`], so the two agree by construction.
  Future<List<CatalogueMatchDto>> matchDevice({
    required String deviceName,
    required List<String> serviceUuids,
  }) => RustLib.instance.api.crateApiSpecHandleCatalogueHandleMatchDevice(
    that: this,
    deviceName: deviceName,
    serviceUuids: serviceUuids,
  );

  /// A handle to the spec at `index`, sharing the catalogue's parse.
  ///
  /// This is how a screen goes from "spec 41 matched" to driving the
  /// device: no re-parse, and no YAML crossing in either direction.
  Future<LoadedSpec> specAt({required int index}) => RustLib.instance.api
      .crateApiSpecHandleCatalogueHandleSpecAt(that: this, index: index);

  /// Every UDP discovery probe the catalogue declares.
  ///
  /// The scan service asks this once and sends what comes back, instead of
  /// holding a constant and a transport per vendor. A spec whose probe is
  /// unusable — no port, or `probe_hex` that is not hex — is left out rather
  /// than reported: discovery is best-effort by nature, and one bad block
  /// should cost that device, not the scan.
  Future<List<UdpProbeDto>> udpBroadcastProbes() => RustLib.instance.api
      .crateApiSpecHandleCatalogueHandleUdpBroadcastProbes(that: this);
}

@sealed
class LoadedSpecImpl extends RustOpaque implements LoadedSpec {
  // Not to be used by end users
  LoadedSpecImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  LoadedSpecImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_LoadedSpec,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_LoadedSpec,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_LoadedSpecPtr,
  );

  /// Decode raw bytes from a BLE read or notification into named values.
