    required String entityName,
    required String stateReply,
  }) => RustLib.instance.api.crateApiSpecHandleLoadedSpecListNetworkInstances(
    that: this,
    entityName: entityName,
    stateReply: stateReply,
  );

  /// Decode one entity's state from the name→value pairs a state call
  /// returned.
  Future<NetworkReadingDto?> readNetworkEntity({
    required String entityName,
    required Map<String, String> returned,
  }) => RustLib.instance.api.crateApiSpecHandleLoadedSpecReadNetworkEntity(
    that: this,
    entityName: entityName,
    returned: returned,
  );

  /// Read one child's roles out of an instanced entity's state reply.
